def transform(grid):
    out=[r[:] for r in grid]
    for r,row in enumerate(grid):
        nz=[c for c,v in enumerate(row) if v]
        if not nz: continue
        for c in range(nz[0]+1,nz[-1]):
            # Internal vertical slot between separate same-color runs.
            if row[c]==0 and row[c-1]!=0 and row[c+1]!=0:
                color=row[c-1]
                for rr in range(r):
                    out[rr][c]=color
    return out

