def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Restore broken horizontal strokes; their colors become vertical strokes
    # from the nearest horizontal line above/below, continuing through blanks.
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v]
        if len(cols) < 2:
            continue
        # Fill only single-cell interruptions bracketed by one common color.
        for c in range(cols[0] + 1, cols[-1]):
            if row[c] == 0 and row[c-1] == row[c+1] and row[c-1] != 0:
                out[r][c] = row[c-1]
    # For every column, project each restored pixel up to the preceding
    # horizontal stripe (or grid edge), preserving original nonzero pixels.
    for c in range(w):
        sources = [r for r in range(h) if out[r][c] != 0 and grid[r][c] == 0]
        for r in sources:
            color = out[r][c]
            rr = r - 1
            while rr >= 0 and grid[rr][c] == 0 and out[rr][c] == 0:
                out[rr][c] = color
                rr -= 1
    return out

